sp_widget.client_script:
api.controller = function() {

    var c = this;

    c.searchQuery = '';
    c.activeCategory = 'all';
    c.sortBy = 'name';
    c.filteredTests = [];


    /* =====================================================
       EXISTING CATEGORY ICONS
       ===================================================== */

    var ICONS = {

        'blood': '🩸',
        'blood test': '🩸',
        'urine': '🧪',
        'imaging': '🩻',
        'radiology': '🩻',
        'cardiology': '❤️',
        'neurology': '🧠',
        'pathology': '🔬',
        'microbiology': '🦠',
        'biochemistry': '⚗️',
        'genetics': '🧬',
        'allergy': '🌿',
        'covid': '😷',
        'diabetes': '💉',
        'thyroid': '🦋',
        'liver': '🫁',
        'kidney': '🫘',
        'vitamin': '💊',
        'iron': '🔩',
        'ecg': '❤️',
        'x-ray': '🩻',
        'xray': '🩻'

    };


    /* =====================================================
       EXISTING CATEGORY ICON FUNCTION
       ===================================================== */

    c.getCategoryIcon = function(category) {

        if (!category)
            return '🔬';

        var key = category.toLowerCase();

        for (var k in ICONS) {

            if (key.indexOf(k) !== -1)
                return ICONS[k];

        }

        return '🔬';

    };


    /* =====================================================
       NEW - TEST SPECIFIC FONT AWESOME ICON
       VISUAL ONLY
       ===================================================== */

    c.getTestIcon = function(test) {

        var name =
            (test.test_name || '').toLowerCase();


        /* X-Ray */

        if (
            name.indexOf('x-ray') !== -1 ||
            name.indexOf('xray') !== -1
        ) {

            return 'fa fa-image';

        }


        /* ECG */

        if (
            name.indexOf('ecg') !== -1 ||
            name.indexOf('electrocardiogram') !== -1
        ) {

            return 'fa fa-heartbeat';

        }


        /* COVID / PCR */

        if (
            name.indexOf('covid') !== -1 ||
            name.indexOf('pcr') !== -1
        ) {

            return 'fa fa-shield';

        }


        /* Thyroid */

        if (
            name.indexOf('thyroid') !== -1
        ) {

            return 'fa fa-leaf';

        }


        /* Diabetes / HbA1c */

        if (
            name.indexOf('diabetes') !== -1 ||
            name.indexOf('hba1c') !== -1
        ) {

            return 'fa fa-tint';

        }


        /* Liver */

        if (
            name.indexOf('liver') !== -1
        ) {

            return 'fa fa-medkit';

        }


        /* Kidney */

        if (
            name.indexOf('kidney') !== -1
        ) {

            return 'fa fa-filter';

        }


        /* Urine */

        if (
            name.indexOf('urine') !== -1
        ) {

            return 'fa fa-flask';

        }


        /* Vitamin */

        if (
            name.indexOf('vitamin') !== -1
        ) {

            return 'fa fa-sun-o';

        }


        /* Iron */

        if (
            name.indexOf('iron') !== -1
        ) {

            return 'fa fa-cubes';

        }


        /* Lipid */

        if (
            name.indexOf('lipid') !== -1
        ) {

            return 'fa fa-flask';

        }


        /* Blood / CBC */

        if (
            name.indexOf('blood') !== -1 ||
            name.indexOf('cbc') !== -1
        ) {

            return 'fa fa-tint';

        }


        /* Default */

        return 'fa fa-flask';

    };


    /* =====================================================
       NEW - TEST ICON COLOR
       VISUAL ONLY
       ===================================================== */

    c.getTestIconClass = function(test) {

        var name =
            (test.test_name || '').toLowerCase();


        /* X-Ray */

        if (
            name.indexOf('x-ray') !== -1 ||
            name.indexOf('xray') !== -1
        ) {

            return 'mn-icon-xray';

        }


        /* ECG */

        if (
            name.indexOf('ecg') !== -1 ||
            name.indexOf('electrocardiogram') !== -1
        ) {

            return 'mn-icon-heart';

        }


        /* COVID */

        if (
            name.indexOf('covid') !== -1 ||
            name.indexOf('pcr') !== -1
        ) {

            return 'mn-icon-covid';

        }


        /* Thyroid */

        if (
            name.indexOf('thyroid') !== -1
        ) {

            return 'mn-icon-thyroid';

        }


        /* Diabetes */

        if (
            name.indexOf('diabetes') !== -1 ||
            name.indexOf('hba1c') !== -1
        ) {

            return 'mn-icon-diabetes';

        }


        /* Liver */

        if (
            name.indexOf('liver') !== -1
        ) {

            return 'mn-icon-liver';

        }


        /* Kidney */

        if (
            name.indexOf('kidney') !== -1
        ) {

            return 'mn-icon-kidney';

        }


        /* Urine */

        if (
            name.indexOf('urine') !== -1
        ) {

            return 'mn-icon-urine';

        }


        /* Vitamin */

        if (
            name.indexOf('vitamin') !== -1
        ) {

            return 'mn-icon-vitamin';

        }


        /* Iron */

        if (
            name.indexOf('iron') !== -1
        ) {

            return 'mn-icon-iron';

        }


        /* Lipid */

        if (
            name.indexOf('lipid') !== -1
        ) {

            return 'mn-icon-lipid';

        }


        /* Blood / CBC */

        return 'mn-icon-blood';

    };


    /* =====================================================
       EXISTING TRUNCATE
       ===================================================== */

    c.truncate = function(text, length) {

        if (!text)
            return 'No description available.';

        return text.length > length
            ? text.substring(0, length) + '...'
            : text;

    };


    /* =====================================================
       EXISTING FILTER
       ===================================================== */

    c.filterTests = function() {

        var all = c.data.tests || [];

        var q =
            (c.searchQuery || '')
            .toLowerCase()
            .trim();

        var cat = c.activeCategory;


        c.filteredTests = all.filter(function(t) {

            var matchSearch =
                !q ||

                (
                    t.test_name &&
                    t.test_name
                        .toLowerCase()
                        .indexOf(q) !== -1
                ) ||

                (
                    t.description &&
                    t.description
                        .toLowerCase()
                        .indexOf(q) !== -1
                ) ||

                (
                    t.test_code &&
                    t.test_code
                        .toLowerCase()
                        .indexOf(q) !== -1
                ) ||

                (
                    t.category &&
                    t.category
                        .toLowerCase()
                        .indexOf(q) !== -1
                );


            var matchCat =
                (cat === 'all') ||
                (t.category === cat);


            return matchSearch && matchCat;

        });


        c.sortTests();

    };


    /* =====================================================
       EXISTING SORT
       ===================================================== */

    c.sortTests = function() {

        var t = c.filteredTests;


        if (c.sortBy === 'name') {

            t.sort(function(a, b) {

                return (a.test_name || '')
                    .localeCompare(
                        b.test_name || ''
                    );

            });

        }


        else if (c.sortBy === 'price_asc') {

            t.sort(function(a, b) {

                return (a.price || 0) -
                    (b.price || 0);

            });

        }


        else if (c.sortBy === 'price_desc') {

            t.sort(function(a, b) {

                return (b.price || 0) -
                    (a.price || 0);

            });

        }


        else if (c.sortBy === 'duration') {

            t.sort(function(a, b) {

                return (a.test_duration || '')
                    .localeCompare(
                        b.test_duration || ''
                    );

            });

        }

    };


    /* =====================================================
       EXISTING CATEGORY FILTER
       ===================================================== */

    c.setCategory = function(cat) {

        c.activeCategory = cat;

        c.filterTests();

    };


    /* =====================================================
       EXISTING CLEAR SEARCH
       ===================================================== */

    c.clearSearch = function() {

        c.searchQuery = '';

        c.filterTests();

    };


    /* =====================================================
       EXISTING RESET FILTERS
       ===================================================== */

    c.resetFilters = function() {

        c.searchQuery = '';

        c.activeCategory = 'all';

        c.sortBy = 'name';

        c.filterTests();

    };


    /* =====================================================
       EXISTING PORTAL HELPER
       ===================================================== */

    var _getPortal = function() {

        return window.location
            .pathname
            .split('/')[1] || 'sp';

    };


    /* =====================================================
       EXISTING BOOK TEST
       NO LOGIC CHANGED
       ===================================================== */

    c.bookTest = function(test) {

        sessionStorage.setItem(
            'selected_test_sys_id',
            test.sys_id
        );

        sessionStorage.setItem(
            'selected_test_name',
            test.test_name || ''
        );

        sessionStorage.setItem(
            'selected_test_price',
            test.price || 0
        );

        sessionStorage.setItem(
            'selected_test_code',
            test.test_code || ''
        );

        sessionStorage.setItem(
            'selected_test_category',
            test.category || ''
        );

        sessionStorage.setItem(
            'selected_test_duration',
            test.test_duration || ''
        );


        window.location.href =
            '/' +
            _getPortal() +
            '?id=book_appointment';

    };


    /* =====================================================
       EXISTING MY BOOKINGS
       ===================================================== */

    c.goToMyBookings = function() {

        window.location.href =
            '/' +
            _getPortal() +
            '?id=book_appointment';

    };


    /* =====================================================
       EXISTING MY REPORTS
       ===================================================== */

    c.goToMyReports = function() {

        window.location.href =
            '/' +
            _getPortal() +
            '?id=lab_reports';

    };


    /* =====================================================
       EXISTING PATIENT DASHBOARD
       ===================================================== */

    c.goToPatientDashboard = function() {

        var portal = _getPortal();

        window.location.href =
            '/' +
            portal +
            '?id=patient_dashboard';

    };


    /* =====================================================
       INIT
       ===================================================== */

    c.filteredTests =
        angular.copy(
            c.data.tests || []
        );

    c.data.totalTests =
        c.filteredTests.length;

    c.sortTests();

};

sp_widget.css:
/* =========================================================
   MEDINOVA DIAGNOSTICS
   HOME PAGE — V3
   VISUAL ONLY
   ========================================================= */

.med-catalog {

  --navy: #123b52;
  --navy-dark: #0b2c3d;

  --teal: #16a6a3;
  --teal-dark: #078b91;
  --teal-light: #e5f7f6;

  --blue: #397acb;
  --blue-light: #eaf2ff;

  --green: #15956f;
  --green-light: #e6f7f1;

  --orange: #df8030;
  --orange-light: #fff1e5;

  --text: #17384d;
  --muted: #708795;

  --border: #dce8ed;
  --background: #f5f9fa;

  width: 100%;
  min-height: 100vh;

  background: var(--background);

  color: var(--text);

  font-family:
    "Segoe UI",
    Arial,
    sans-serif;

  padding-bottom: 50px;

  box-sizing: border-box;

}


/* =========================================================
   HERO
   ========================================================= */

.mn-hero-v3 {

  position: relative;

  min-height: 500px;

  padding: 55px 6% 75px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  overflow: hidden;

  background:
    linear-gradient(
      125deg,
      #0d3047 0%,
      #155675 55%,
      #118c91 100%
    );

}


/* BACKGROUND CIRCLES */

.mn-hero-bg-circle {

  position: absolute;

  border-radius: 50%;

  border: 1px solid rgba(255,255,255,.10);

  pointer-events: none;

}

.circle-one {

  width: 480px;
  height: 480px;

  right: -190px;
  top: -210px;

}

.circle-two {

  width: 280px;
  height: 280px;

  right: 250px;
  bottom: -190px;

}


/* =========================================================
   HERO LEFT
   ========================================================= */

.mn-hero-content-v3 {

  position: relative;

  z-index: 5;

  width: 57%;

  max-width: 680px;

}


/* =========================================================
   BRAND
   ========================================================= */

.mn-brand-v3 {

  display: flex;

  align-items: center;

  gap: 12px;

  margin-bottom: 25px;

}


.mn-brand-icon {

  width: 48px;
  height: 48px;

  border-radius: 13px;

  background: #ffffff;

  display: flex;

  align-items: center;

  justify-content: center;

  color: var(--teal);

  font-size: 25px;

  box-shadow:
    0 8px 25px rgba(0,0,0,.18);

}


.mn-brand-name strong {

  display: block;

  color: #ffffff;

  font-size: 20px;

  font-weight: 800;

  letter-spacing: 2px;

  line-height: 1;

}


.mn-brand-name span {

  display: block;

  margin-top: 5px;

  color: #b8dce2;

  font-size: 8px;

  font-weight: 700;

  letter-spacing: 2px;

}


/* =========================================================
   TRUST LABEL
   ========================================================= */

.mn-trust-label {

  display: inline-flex;

  align-items: center;

  gap: 8px;

  padding: 7px 13px;

  border-radius: 25px;

  background: rgba(255,255,255,.10);

  border: 1px solid rgba(255,255,255,.18);

  color: #d8f5f2;

  font-size: 10px;

  font-weight: 700;

  letter-spacing: .8px;

  text-transform: uppercase;

}


.mn-live-dot {

  width: 7px;
  height: 7px;

  border-radius: 50%;

  background: #55ddb0;

  box-shadow:
    0 0 0 4px rgba(85,221,176,.12);

}


/* =========================================================
   HERO TITLE
   ========================================================= */

.mn-hero-title-v3 {

  margin: 20px 0 15px;

  color: #ffffff;

  font-size: 47px;

  font-weight: 800;

  line-height: 1.08;

  letter-spacing: -1.4px;

}


.mn-hero-title-v3 span {

  display: block;

  color: #69d7d1;

}


/* =========================================================
   HERO DESCRIPTION
   ========================================================= */

.mn-hero-subtitle-v3 {

  max-width: 590px;

  margin: 0 0 25px;

  color: #c8dce4;

  font-size: 14px;

  line-height: 1.7;

}


/* =========================================================
   SEARCH
   ========================================================= */

.mn-search-v3 {

  position: relative;

  width: 100%;

  max-width: 580px;

  height: 56px;

  display: flex;

  align-items: center;

  background: #ffffff;

  border-radius: 13px;

  border: 1px solid rgba(255,255,255,.3);

  box-shadow:
    0 12px 30px rgba(0,0,0,.18);

  transition:
    border-color .2s ease,
    box-shadow .2s ease;

}


.mn-search-v3:focus-within {

  border-color: #50d3ce;

  box-shadow:
    0 14px 35px rgba(0,0,0,.22);

}


.mn-search-v3 > i {

  margin-left: 18px;

  color: var(--teal);

  font-size: 16px;

}


.mn-search-v3 input {

  flex: 1;

  height: 100%;

  min-width: 0;

  padding: 0 15px;

  border: none;

  outline: none;

  background: transparent;

  color: #17384d;

  font-size: 14px;

}


.mn-search-v3 input::placeholder {

  color: #9aacb5;

}


.mn-search-clear {

  width: 36px;
  height: 36px;

  margin-right: 9px;

  border: none;

  border-radius: 9px;

  background: #edf7f7;

  color: #78959d;

  cursor: pointer;

}


.mn-search-clear:hover {

  background: #dff1f0;

  color: var(--teal);

}


/* =========================================================
   TRUST FEATURES
   ========================================================= */

.mn-trust-features {

  display: flex;

  align-items: center;

  gap: 25px;

  margin-top: 22px;

  flex-wrap: wrap;

}


.mn-trust-item {

  display: flex;

  align-items: center;

  gap: 8px;

}


.mn-trust-icon {

  width: 28px;
  height: 28px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 8px;

  background: rgba(255,255,255,.10);

  color: #64dcd5;

}


.mn-trust-icon i {

  font-size: 11px;

}


.mn-trust-item strong {

  display: block;

  color: #e0f1f3;

  font-size: 10px;

}


.mn-trust-item small {

  display: block;

  margin-top: 2px;

  color: #9fc1ca;

  font-size: 8px;

}


/* =========================================================
   HERO RIGHT
   ========================================================= */

.mn-hero-visual-v3 {

  position: relative;

  width: 39%;

  min-height: 420px;

  display: flex;

  align-items: center;

  justify-content: center;

}


/* ORBITS */

.mn-orbit {

  position: absolute;

  border-radius: 50%;

  border: 1px solid rgba(255,255,255,.13);

}


.orbit-one {

  width: 330px;
  height: 330px;

}


.orbit-two {

  width: 245px;
  height: 245px;

}


/* =========================================================
   MEDICAL PANEL
   ========================================================= */

.mn-medical-panel {

  position: relative;

  z-index: 3;

  width: 285px;

  min-height: 330px;

  padding: 22px;

  box-sizing: border-box;

  border-radius: 25px;

  background:
    linear-gradient(
      145deg,
      #0c5667 0%,
      #117d82 100%
    );

  box-shadow:
    0 25px 60px rgba(0,0,0,.20);

  overflow: hidden;

}


.mn-medical-panel::before {

  content: "";

  position: absolute;

  width: 230px;
  height: 230px;

  border-radius: 50%;

  right: -120px;
  top: -80px;

  border: 1px solid rgba(255,255,255,.12);

}


.mn-panel-top {

  position: relative;

  z-index: 2;

  display: flex;

  align-items: center;

  justify-content: space-between;

}


.mn-panel-top > span:first-child {

  color: #b7e5e3;

  font-size: 8px;

  font-weight: 800;

  letter-spacing: 1.5px;

}


.mn-panel-live {

  display: flex;

  align-items: center;

  gap: 5px;

  padding: 4px 8px;

  border-radius: 20px;

  background: rgba(255,255,255,.10);

  color: #d8fffa;

  font-size: 8px;

  font-weight: 700;

}


.mn-panel-live b {

  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: #5cddb4;

}


/* =========================================================
   MEDICAL SYMBOL
   ========================================================= */

.mn-medical-symbol {

  width: 115px;
  height: 115px;

  margin: 45px auto 20px;

  border-radius: 32px;

  background: #ffffff;

  color: var(--teal);

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 55px;

  box-shadow:
    0 16px 35px rgba(0,0,0,.17);

}


.mn-panel-title {

  position: relative;

  color: #ffffff;

  text-align: center;

  font-size: 18px;

  font-weight: 700;

}


.mn-panel-subtitle {

  margin-top: 5px;

  color: #b9dfdf;

  text-align: center;

  font-size: 9px;

}


.mn-panel-line {

  height: 1px;

  margin: 20px 0 15px;

  background: rgba(255,255,255,.13);

}


.mn-panel-footer {

  display: flex;

  justify-content: center;

  gap: 45px;

  text-align: center;

}


.mn-panel-footer strong {

  display: block;

  color: #ffffff;

  font-size: 18px;

}


.mn-panel-footer span {

  display: block;

  margin-top: 3px;

  color: #a9d5d5;

  font-size: 8px;

}


/* =========================================================
   FLOATING CARDS
   ========================================================= */

.mn-floating-stat {

  position: absolute;

  z-index: 6;

  display: flex;

  align-items: center;

  gap: 9px;

  padding: 11px 14px;

  min-width: 135px;

  background: #ffffff;

  border: 1px solid #dfebed;

  border-radius: 13px;

  box-shadow:
    0 15px 35px rgba(20,70,80,.15);

}


.mn-floating-tests {

  top: 50px;

  right: -5px;

}


.mn-floating-report {

  bottom: 55px;

  left: -5px;

}


.mn-floating-icon {

  width: 36px;
  height: 36px;

  border-radius: 10px;

  display: flex;

  align-items: center;

  justify-content: center;

  background: #e4f7f6;

  color: var(--teal);

}


.report-icon {

  background: #eef2fb;

  color: #5974b8;

}


.mn-floating-stat strong {

  display: block;

  color: var(--navy);

  font-size: 18px;

  line-height: 1;

}


.mn-floating-stat span {

  display: block;

  margin-top: 4px;

  color: #8ba0a8;

  font-size: 8px;

}


/* =========================================================
   QUICK ACTIONS
   ========================================================= */

.mn-actions-v3 {

  position: relative;

  z-index: 20;

  max-width: 1160px;

  margin: -35px auto 0;

  padding: 0 20px;

  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 15px;

}


.mn-action-card {

  min-height: 76px;

  padding: 13px 15px;

  display: flex;

  align-items: center;

  gap: 11px;

  background: #ffffff;

  border: 1px solid #dfe9ed;

  border-radius: 14px;

  box-shadow:
    0 10px 28px rgba(30,65,80,.10);

  cursor: pointer;

  transition:
    transform .2s ease,
    box-shadow .2s ease,
    border-color .2s ease;

}


.mn-action-card:hover {

  transform: translateY(-4px);

  border-color: #8dd7d2;

  box-shadow:
    0 16px 32px rgba(30,65,80,.15);

}


.mn-action-icon {

  width: 43px;
  height: 43px;

  flex-shrink: 0;

  border-radius: 11px;

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 16px;

}


.mn-action-icon.blue {

  background: var(--blue-light);

  color: var(--blue);

}


.mn-action-icon.green {

  background: var(--green-light);

  color: var(--green);

}


.mn-action-icon.orange {

  background: var(--orange-light);

  color: var(--orange);

}


.mn-action-content {

  flex: 1;

  min-width: 0;

}


.mn-action-content strong {

  display: block;

  color: var(--navy);

  font-size: 12px;

  font-weight: 700;

}


.mn-action-content span {

  display: block;

  margin-top: 4px;

  color: #8ca0aa;

  font-size: 9px;

}


.mn-action-arrow {

  color: #91a8b2;

  font-size: 11px;

}


.mn-action-card:hover .mn-action-arrow {

  color: var(--teal);

}


/* =========================================================
   TEST SECTION HEADER
   ========================================================= */

.mn-test-heading-v3 {

  max-width: 1160px;

  margin: 55px auto 0;

  padding: 0 20px;

  display: flex;

  align-items: flex-end;

  justify-content: space-between;

}


.mn-section-label {

  display: block;

  margin-bottom: 7px;

  color: var(--teal);

  font-size: 9px;

  font-weight: 800;

  letter-spacing: 1.5px;

}


.mn-test-heading-v3 h2 {

  margin: 0;

  color: var(--navy);

  font-size: 28px;

  font-weight: 800;

  letter-spacing: -.5px;

}


.mn-test-heading-v3 p {

  margin: 7px 0 0;

  color: var(--muted);

  font-size: 12px;

}


.mn-total-tests-v3 {

  text-align: right;

}


.mn-total-tests-v3 strong {

  display: block;

  color: var(--teal);

  font-size: 27px;

  font-weight: 800;

}


.mn-total-tests-v3 span {

  color: var(--muted);

  font-size: 9px;

}


/* =========================================================
   CATEGORY
   ========================================================= */

.mn-category-v3 {

  max-width: 1160px;

  margin: 22px auto 0;

  padding: 0 20px;

  display: flex;

  align-items: center;

  gap: 8px;

  flex-wrap: wrap;

}


.mn-category-button {

  padding: 8px 15px;

  border-radius: 20px;

  border: 1px solid var(--border);

  background: #ffffff;

  color: var(--muted);

  font-size: 10px;

  font-weight: 600;

  cursor: pointer;

  transition: all .2s ease;

}


.mn-category-button:hover {

  border-color: var(--teal);

  color: var(--teal);

}


.mn-category-button.active {

  background: var(--navy);

  border-color: var(--navy);

  color: #ffffff;

  box-shadow:
    0 5px 13px rgba(18,59,82,.17);

}


/* =========================================================
   RESULTS
   ========================================================= */

.mn-results-v3 {

  max-width: 1160px;

  margin: auto;

  padding: 22px 20px 3px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 15px;

}


.mn-results-count {

  color: var(--muted);

  font-size: 11px;

}


.mn-results-count strong {

  color: var(--navy);

}


.mn-results-count em {

  color: var(--teal);

  font-style: normal;

}


.mn-sort {

  display: flex;

  align-items: center;

  gap: 7px;

}


.mn-sort label {

  color: var(--muted);

  font-size: 10px;

}


.mn-sort select {

  padding: 7px 28px 7px 10px;

  border: 1px solid var(--border);

  border-radius: 7px;

  background: #ffffff;

  color: var(--text);

  font-size: 10px;

  outline: none;

  cursor: pointer;

}


.mn-sort select:focus {

  border-color: var(--teal);

}


/* =========================================================
   TEST GRID
   EXACTLY 3 COLUMNS
   ========================================================= */

.mn-tests-v3 {

  max-width: 1200px;

  margin: 0 auto;

  padding: 20px;

  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 20px;

}


/* =========================================================
   TEST CARD
   ========================================================= */

.mn-test-card-v3 {

  min-width: 0;

  background: #ffffff;

  border: 1px solid var(--border);

  border-radius: 15px;

  overflow: hidden;

  display: flex;

  flex-direction: column;

  box-shadow:
    0 4px 14px rgba(30,65,80,.055);

  transition:
    transform .2s ease,
    box-shadow .2s ease,
    border-color .2s ease;

}


.mn-test-card-v3:hover {

  transform: translateY(-5px);

  border-color: #83d6d1;

  box-shadow:
    0 16px 35px rgba(30,65,80,.13);

}


/* =========================================================
   CARD HEADER
   ========================================================= */

.mn-card-header-v3 {

  min-height: 108px;

  padding: 16px 17px;

  display: flex;

  align-items: flex-start;

  justify-content: space-between;

  box-sizing: border-box;

  background:
    linear-gradient(
      135deg,
      #edf9f9 0%,
      #f9fcfd 100%
    );

  border-bottom: 1px solid #e7eff2;

}


/* =========================================================
   TEST ICON
   ========================================================= */

.mn-test-icon-v3 {

  width: 56px;
  height: 56px;

  border-radius: 14px;

  background: #ffffff;

  display: flex;

  align-items: center;

  justify-content: center;

  box-shadow:
    0 5px 14px rgba(30,65,80,.08);

}


/* IMPORTANT:
   Different icons are now returned by your existing
   c.getCategoryIcon(test.test_name)
*/

.mn-test-icon-v3 .test-icon {

  font-size: 27px;

  line-height: 1;

}


/* =========================================================
   BADGES
   ========================================================= */

.mn-card-badges {

  display: flex;

  flex-direction: column;

  align-items: flex-end;

  gap: 6px;

}


.mn-category-badge {

  padding: 5px 9px;

  border-radius: 20px;

  background: #e4f1ff;

  border: 1px solid #c9e1f7;

  color: #1769aa;

  font-size: 9px;

  font-weight: 700;

  line-height: 1;

}


.mn-available-badge {

  display: flex;

  align-items: center;

  gap: 5px;

  padding: 5px 9px;

  border-radius: 20px;

  background: #e0f7ed;

  border: 1px solid #c6ecdc;

  color: #147a59;

  font-size: 9px;

  font-weight: 700;

  line-height: 1;

}


.mn-available-badge span {

  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: #159a72;

}


.mn-unavailable-badge {

  padding: 5px 9px;

  border-radius: 20px;

  background: #fee7e8;

  color: #b4232e;

  font-size: 9px;

  font-weight: 700;

}


/* =========================================================
   CARD BODY
   ========================================================= */

.mn-card-body-v3 {

  flex: 1;

  padding: 19px;

}


.mn-test-label {

  display: block;

  margin-bottom: 7px;

  color: var(--teal-dark);

  font-size: 8px;

  font-weight: 800;

  letter-spacing: 1.3px;

}


.mn-card-body-v3 h3 {

  margin: 0 0 6px;

  color: var(--navy);

  font-size: 17px;

  font-weight: 700;

  line-height: 1.3;

}


.mn-test-code {

  margin-bottom: 13px;

  color: #98aab4;

  font-size: 9px;

}


.mn-test-code strong {

  color: var(--blue);

}


.mn-test-description {

  min-height: 40px;

  margin: 0 0 16px;

  color: var(--muted);

  font-size: 12px;

  line-height: 1.65;

}


/* =========================================================
   META
   ========================================================= */

.mn-test-meta-v3 {

  display: flex;

  align-items: center;

  gap: 18px;

  padding-top: 12px;

  border-top: 1px solid #edf2f4;

}


.mn-meta-item {

  display: flex;

  align-items: center;

  gap: 6px;

  color: var(--muted);

  font-size: 10px;

}


.mn-meta-item i {

  color: var(--teal);

  font-size: 11px;

}


/* =========================================================
   CARD FOOTER
   ========================================================= */

.mn-card-footer-v3 {

  min-height: 76px;

  padding: 13px 17px;

  box-sizing: border-box;

  display: flex;

  align-items: center;

  justify-content: space-between;

  background: #fbfdfe;

  border-top: 1px solid #edf2f4;

}


.mn-price {

  display: flex;

  flex-direction: column;

}


.mn-price span {

  color: #8b9da7;

  font-size: 9px;

}


.mn-price strong {

  margin-top: 2px;

  color: var(--navy);

  font-size: 22px;

  font-weight: 800;

  line-height: 1;

}


/* =========================================================
   BOOK BUTTON
   ========================================================= */

.mn-book-button {

  display: flex;

  align-items: center;

  gap: 8px;

  padding: 11px 17px;

  border: none;

  border-radius: 9px;

  background:
    linear-gradient(
      135deg,
      #16aaa7,
      #078d96
    );

  color: #ffffff !important;

  font-size: 12px;

  font-weight: 700;

  cursor: pointer;

  box-shadow:
    0 6px 16px rgba(0,150,155,.22);

  transition:
    transform .2s ease,
    box-shadow .2s ease;

}


.mn-book-button:hover {

  transform: translateY(-2px);

  box-shadow:
    0 9px 20px rgba(0,150,155,.30);

}


.mn-book-button i {

  color: #ffffff;

}


.mn-book-button.disabled {

  background: #e5eaed !important;

  color: #8999a4 !important;

  box-shadow: none;

  cursor: not-allowed;

}


/* =========================================================
   EMPTY STATE
   ========================================================= */

.mn-empty-v3 {

  padding: 75px 20px;

  text-align: center;

}


.mn-empty-icon {

  width: 65px;
  height: 65px;

  margin: 0 auto 18px;

  border-radius: 50%;

  background: var(--teal-light);

  color: var(--teal);

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 23px;

}


.mn-empty-v3 h3 {

  margin: 0 0 8px;

  color: var(--navy);

  font-size: 20px;

}


.mn-empty-v3 p {

  margin: 0 0 20px;

  color: var(--muted);

  font-size: 12px;

}


.mn-reset {

  padding: 9px 20px;

  border: none;

  border-radius: 8px;

  background: var(--navy);

  color: #ffffff;

  font-weight: 600;

  cursor: pointer;

}


/* =========================================================
   FOOTER
   ========================================================= */

.mn-footer-v3 {

  max-width: 1160px;

  margin: 25px auto 0;

  padding: 22px 20px;

  border-top: 1px solid var(--border);

  display: flex;

  align-items: center;

  gap: 10px;

}


.mn-footer-mark {

  width: 34px;
  height: 34px;

  border-radius: 9px;

  background: var(--navy);

  color: #ffffff;

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 17px;

}


.mn-footer-v3 strong {

  display: block;

  color: var(--navy);

  font-size: 10px;

  letter-spacing: 1px;

}


.mn-footer-v3 span {

  display: block;

  margin-top: 4px;

  color: var(--muted);

  font-size: 9px;

}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 950px) {

  .mn-hero-v3 {

    padding-left: 35px;

    padding-right: 35px;

  }

  .mn-hero-content-v3 {

    width: 100%;

  }

  .mn-hero-visual-v3 {

    display: none;

  }

  .mn-hero-title-v3 {

    font-size: 40px;

  }

}


@media (max-width: 850px) {

  .mn-tests-v3 {

    grid-template-columns:
      repeat(2, minmax(0, 1fr));

  }

}


@media (max-width: 700px) {

  .mn-actions-v3 {

    grid-template-columns: 1fr;

  }

  .mn-test-heading-v3 {

    align-items: flex-start;

  }

  .mn-total-tests-v3 {

    display: none;

  }

  .mn-results-v3 {

    flex-direction: column;

    align-items: flex-start;

  }

  .mn-tests-v3 {

    grid-template-columns: 1fr;

  }

}


@media (max-width: 500px) {

  .mn-hero-v3 {

    padding:
      35px 20px 60px;

  }

  .mn-hero-title-v3 {

    font-size: 31px;

  }

  .mn-hero-subtitle-v3 {

    font-size: 13px;

  }

  .mn-trust-features {

    gap: 13px;

  }

  .mn-trust-item small {

    display: none;

  }

  .mn-actions-v3 {

    padding: 0 15px;

  }

  .mn-test-heading-v3 {

    padding: 0 15px;

  }

  .mn-category-v3 {

    padding: 0 15px;

  }

  .mn-results-v3 {

    padding-left: 15px;

    padding-right: 15px;

  }

  .mn-tests-v3 {

    padding: 15px;

  }

  .mn-card-footer-v3 {

    padding-left: 14px;

    padding-right: 14px;

  }

}

sp_widget.script:
(function() {
  data.tests = [];
  data.categories = [];
  data.totalTests = 0;
  try {
    var testGr = new GlideRecord('x_2056616_medica_0_diagnostic_test');
    testGr.orderBy('test_name');
    testGr.query();
    var categorySet = {};
    var categoryList = [];
    while (testGr.next()) {
      var categoryDisplay = testGr.getDisplayValue('category') || testGr.getValue('category') || 'General';
      var activeVal = testGr.getValue('active');
      var isActive = (activeVal === '1' || activeVal === 'true' || activeVal === true);
      data.tests.push({
        sys_id:        testGr.getUniqueValue(),
        test_name:     testGr.getValue('test_name')     || '',
        test_code:     testGr.getValue('test_code')     || '',
        category:      categoryDisplay,
        description:   testGr.getValue('description')   || '',
        price:         parseFloat(testGr.getValue('price')) || 0,
        test_duration: testGr.getValue('test_duration') || '',
        active:        isActive
      });
      if (categoryDisplay && !categorySet[categoryDisplay]) {
        categorySet[categoryDisplay] = true;
        categoryList.push(categoryDisplay);
      }
    }
    categoryList.sort();
    data.categories = categoryList;
    data.totalTests = data.tests.length;
  } catch(e) {
    data.error = e.message;
    gs.error('MediCare Catalog Error: ' + e.message);
  }
})();
